function flattenAirtable(items) {
  const out = [];
  for (const item of items || []) {
    const records = item && item.json && Array.isArray(item.json.records) ? item.json.records : [];
    for (const record of records) {
      out.push(Object.assign({ record_id: record.id }, record.fields || {}));
    }
  }
  return out;
}

function configMap(rows) {
  const map = {};
  for (const row of rows || []) {
    if (row.key) map[row.key] = row.value;
  }
  return map;
}

function chunkRecords(list, size) {
  const out = [];
  for (let i = 0; i < list.length; i += size) out.push(list.slice(i, i + size));
  return out;
}

/**
 * Cadence selection, prompts, and reply guardrails for the v2 demo.
 *
 * The v1 build had a single 90-day touch. v2 runs a four-stage program driven
 * entirely by cohort, which is derived from lease_end_date alone:
 *
 *   120 -> WATCH_120    watchlist only, no resident contact
 *    90 -> CHECK_IN_90  soft check-in, emailed on approval
 *    60 -> NUDGE_60     only for residents who never replied to the 90-day touch
 *    30 -> HANDOFF_30   internal leasing handoff, never emails the resident
 *
 * Draft guardrails for outbound check-ins are reused from
 * scripts/stage-5-outbound-lib.js. Replies and fix-confirmations need different
 * rules (they may reference the resident's issue and are not limited to one
 * question), so guardReply() is defined here.
 *
 * This file is inlined into n8n Code nodes at import time, so it stays
 * dependency-free.
 */

const TOUCH = {
  WATCH_120: "WATCH_120",
  CHECK_IN_90: "CHECK_IN_90",
  NUDGE_60: "NUDGE_60",
  HANDOFF_30: "HANDOFF_30",
};

const TOUCH_BY_COHORT = {
  120: TOUCH.WATCH_120,
  90: TOUCH.CHECK_IN_90,
  60: TOUCH.NUDGE_60,
  30: TOUCH.HANDOFF_30,
};

const TOUCH_LABEL = {
  [TOUCH.WATCH_120]: "120-day watchlist",
  [TOUCH.CHECK_IN_90]: "90-day check-ins",
  [TOUCH.NUDGE_60]: "60-day nudges",
  [TOUCH.HANDOFF_30]: "30-day leasing handoff",
};

/** Touches that may result in an email to a resident. */
const EMAILING_TOUCHES = new Set([TOUCH.CHECK_IN_90, TOUCH.NUDGE_60]);

function txt(value) {
  return value == null ? "" : String(value).trim();
}

function bool(value) {
  if (typeof value === "boolean") return value;
  const text = txt(value).toLowerCase();
  return text === "true" || text === "1" || text === "yes";
}

function daysBetween(fromIso, toIso) {
  const from = new Date(fromIso);
  const to = new Date(toIso);
  if (Number.isNaN(from.getTime()) || Number.isNaN(to.getTime())) return null;
  return Math.floor((to.getTime() - from.getTime()) / 86400000);
}

/**
 * Airtable stores no email_valid flag. Validity is derived from the address and
 * the data-quality notes written at seed time, mirroring v1's isValidEmail().
 */
function emailValidFor(lease) {
  const email = txt(lease.email);
  if (!email) return false;
  const notes = txt(lease.data_quality).toUpperCase();
  if (notes.includes("MISSING_EMAIL") || notes.includes("INVALID_EMAIL")) return false;
  return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email);
}

function touchForCohort(cohort) {
  return TOUCH_BY_COHORT[txt(cohort)] || null;
}

/**
 * True when a resident received the 90-day check-in, enough time has passed, and
 * no meaningful reply ever came back. NO_SIGNAL auto-replies do not count as a reply.
 */
function isSilentAfterCheckIn(lease, logRows, config, nowIso) {
  if (txt(lease.status).toUpperCase() !== "SENT") return false;
  const sentAt = txt(lease.sent_at);
  if (!sentAt) return false;

  const elapsed = daysBetween(sentAt, nowIso);
  const threshold = Number(config.nudge_after_days || 14);
  if (elapsed == null || elapsed < threshold) return false;

  const meaningful = (logRows || []).some((row) => {
    if (txt(row.lease_id) !== txt(lease.lease_id)) return false;
    if (txt(row.event_type) !== "REPLY_RECEIVED") return false;
    return txt(row.intent).toUpperCase() !== "NO_SIGNAL";
  });

  return !meaningful;
}

/**
 * Splits the roster into the four cadence stages.
 * Nothing here consults anything except cohort, status, opt-out, and reply history.
 */
function selectTouchCandidates(leases, logRows, config, nowIso) {
  const result = {
    [TOUCH.WATCH_120]: [],
    [TOUCH.CHECK_IN_90]: [],
    [TOUCH.NUDGE_60]: [],
    [TOUCH.HANDOFF_30]: [],
    skipped: [],
  };

  const seen = new Set();

  for (const lease of leases || []) {
    const leaseId = txt(lease.lease_id);
    if (!leaseId || seen.has(leaseId)) continue;
    seen.add(leaseId);

    const touch = touchForCohort(lease.cohort);
    if (!touch) continue;

    if (bool(lease.opted_out)) {
      result.skipped.push({ lease, reason: "opted_out" });
      continue;
    }

    if (touch === TOUCH.WATCH_120 || touch === TOUCH.HANDOFF_30) {
      result[touch].push(lease);
      continue;
    }

    if (!emailValidFor(lease)) {
      result.skipped.push({ lease, reason: "no_usable_email" });
      continue;
    }

    if (touch === TOUCH.CHECK_IN_90) {
      if (txt(lease.status).toUpperCase() !== "PENDING") {
        result.skipped.push({ lease, reason: `status_${txt(lease.status).toLowerCase()}` });
        continue;
      }
      result[touch].push(lease);
      continue;
    }

    if (touch === TOUCH.NUDGE_60) {
      if (!isSilentAfterCheckIn(lease, logRows, config, nowIso)) {
        result.skipped.push({ lease, reason: "not_silent" });
        continue;
      }
      result[touch].push(lease);
    }
  }

  for (const touch of Object.keys(TOUCH_BY_COHORT).map((cohort) => TOUCH_BY_COHORT[cohort])) {
    result[touch].sort((a, b) => Number(a.days_to_expiry || 9999) - Number(b.days_to_expiry || 9999));
  }

  return result;
}

/* ---------------------------------------------------------------- prompts */

function touchPromptInstructions(touch) {
  const shared = [
    "You write short, plain, human property-management emails.",
    "Never mention rent, price, renewal, lease terms, deadlines, legal matters, or eviction.",
    "Never state or imply a date.",
    "Never mention software, automation, or AI.",
    "No exclamation marks, bullets, or emoji.",
    "Address the resident by first name.",
  ];

  if (touch === TOUCH.NUDGE_60) {
    return [
      ...shared,
      "This is a second, lighter message to a resident who did not reply to an earlier check-in.",
      "Acknowledge briefly that you reached out before, without any hint of pressure or complaint.",
      "Body must be 30 to 70 words and contain exactly one question.",
    ].join(" ");
  }

  return [
    ...shared,
    "This is a soft check-in months before any renewal conversation.",
    "Include one natural reference to how long they have lived there.",
    "Body must be 35 to 95 words and contain exactly one question about anything that is not sorted out.",
  ].join(" ");
}

function buildTouchPrompt(touch, candidates, config) {
  const managerName = txt(config.manager_name) || "the property manager";
  const companyName = txt(config.company_name) || "the property team";

  const rows = (candidates || []).map((lease) => ({
    lease_id: txt(lease.lease_id),
    tenant_first_name: txt(lease.tenant_first_name),
    unit: txt(lease.unit),
    tenure_months: lease.tenure_months,
  }));

  return [
    touchPromptInstructions(touch),
    `Sign every message as ${managerName} at ${companyName}.`,
    "Return one draft per resident with keys lease_id, subject, and body.",
    "",
    JSON.stringify({ residents: rows }),
  ].join("\n");
}

/**
 * Prompt for a suggested reply to a resident who raised an issue.
 * The manager approves the result before anything sends.
 */
function buildAssistPrompt(lease, config) {
  const managerName = txt(config.manager_name) || "the property manager";
  const companyName = txt(config.company_name) || "the property team";

  return [
    "Write a short reply from a property manager to a resident who raised an issue.",
    "Acknowledge the specific issue in their own terms and say what happens next in general terms.",
    "Never promise a date, a cost, a repair outcome, or a renewal or rent decision.",
    "Never reference legal matters, lease terms, or eviction.",
    "Never mention software, automation, or AI.",
    "No exclamation marks, bullets, or emoji.",
    "Keep the body between 30 and 90 words. Address the resident by first name.",
    `Sign as ${managerName} at ${companyName}.`,
    "Return JSON with keys subject and body.",
    "",
    JSON.stringify({
      tenant_first_name: txt(lease.tenant_first_name),
      unit: txt(lease.unit),
      resident_message: txt(lease.reply_text),
      issue_summary: txt(lease.suggested_action),
    }),
  ].join("\n");
}

/**
 * Prompt for the fix-confirmation sent after a manager marks an issue resolved.
 */
function buildConfirmationPrompt(lease, config) {
  const managerName = txt(config.manager_name) || "the property manager";
  const companyName = txt(config.company_name) || "the property team";

  return [
    "Write a short follow-up from a property manager to a resident whose reported issue has now been dealt with.",
    "Reference the issue they raised and ask one question confirming it is genuinely resolved for them.",
    "Never promise anything further, and never mention rent, renewal, lease terms, deadlines, or legal matters.",
    "Never mention software, automation, or AI.",
    "No exclamation marks, bullets, or emoji.",
    "Keep the body between 25 and 80 words. Address the resident by first name.",
    `Sign as ${managerName} at ${companyName}.`,
    "Return JSON with keys subject and body.",
    "",
    JSON.stringify({
      tenant_first_name: txt(lease.tenant_first_name),
      unit: txt(lease.unit),
      original_message: txt(lease.reply_text),
    }),
  ].join("\n");
}

/* ------------------------------------------------------------- guardrails */

/**
 * Guardrail for resident-facing replies and confirmations.
 *
 * Deliberately looser than guardDraft() in stage-5-outbound-lib.js: a reply may
 * reference the resident's issue and is not held to exactly one question. The
 * hard boundaries - money, renewal, legal, dates, promises - still apply.
 */
function guardReply(lease, subject, body) {
  const cleanSubject = txt(subject);
  const cleanBody = txt(body);
  const combined = `${cleanSubject}\n${cleanBody}`;
  const violations = [];

  const banned = /\b(renew\w*|rent|lease\s+term|evict\w*|legal|attorney|lawyer|notice\s+to|nonrenew\w*)\b/i;
  const money = /(\$\s?\d|\d+\s?%|\bdollars?\b|\bcents?\b)/i;
  const dateLike = /\b(?:jan(?:uary)?|feb(?:ruary)?|mar(?:ch)?|apr(?:il)?|jun(?:e)?|jul(?:y)?|aug(?:ust)?|sep(?:t(?:ember)?)?|oct(?:ober)?|nov(?:ember)?|dec(?:ember)?)\b|\b\d{1,2}[/-]\d{1,2}(?:[/-]\d{2,4})?\b|\b\d{4}-\d{2}-\d{2}\b/i;
  const promise = /\b(guarantee\w*|we will (?:fix|repair|replace|resolve|complete)|by (?:tomorrow|monday|tuesday|wednesday|thursday|friday|saturday|sunday)|within \d+\s*(?:hours?|days?|weeks?))\b/i;

  const words = cleanBody.split(/\s+/).filter(Boolean).length;
  const firstName = txt(lease.tenant_first_name);

  if (!cleanSubject) violations.push("missing subject");
  if (!cleanBody) violations.push("missing body");
  if (banned.test(combined)) violations.push("banned rent, renewal, lease, or legal wording");
  if (money.test(combined)) violations.push("money or percentage wording");
  if (dateLike.test(combined)) violations.push("date or deadline-like wording");
  if (promise.test(combined)) violations.push("promises a specific outcome or timeframe");
  if (words < 20) violations.push("body under 20 words");
  if (words > 110) violations.push("body over 110 words");
  if (/!|•|[\u{1F300}-\u{1FAFF}]/u.test(cleanBody)) violations.push("exclamation mark, bullet, or emoji");
  if (/generated|software|automation|ai-assisted|artificial intelligence/i.test(combined)) {
    violations.push("mentions automation or AI");
  }
  if (firstName && !new RegExp(`\\b${firstName.replace(/[.*+?^${}()|[\]\\]/g, "\\$&")}\\b`, "i").test(cleanBody)) {
    violations.push("missing resident first name");
  }

  return { ok: violations.length === 0, violations, word_count: words };
}
/**
 * Demo scoreboard maths for the v2 Metrics table and the Telegram digest.
 *
 * The headline number is turnover exposure: the money at risk in the residents
 * currently flagged AT_RISK or ESCALATE, valued at config.avg_turnover_cost.
 * Exposure recovered is the same figure for issues a manager has closed.
 *
 * These are demo-grade proxies, not a financial model. The POC does not claim a
 * resolved issue guarantees a renewal - only that the exposure was surfaced and
 * acted on. Say that out loud when presenting the number.
 *
 * This file is inlined into n8n Code nodes at import time.
 */

const AT_RISK_STATUSES = new Set(["AT_RISK", "ESCALATE"]);

function txt(value) {
  return value == null ? "" : String(value).trim();
}

function num(value, fallback = 0) {
  const parsed = Number(value);
  return Number.isFinite(parsed) ? parsed : fallback;
}

function round1(value) {
  return Math.round(value * 10) / 10;
}

/**
 * @param {Array} leases  every lease row
 * @param {Array} logRows every outreach log row
 * @param {object} config config key/value map
 */
function computeMetrics(leases, logRows, config = {}) {
  const rows = leases || [];
  const log = logRows || [];
  const turnoverCost = num(config.avg_turnover_cost, 3900);

  const residentsInWindow = rows.filter((lease) => txt(lease.cohort) === "90").length;

  const checkInsSent = log.filter((row) => txt(row.event_type) === "SENT").length;
  const repliesReceived = log.filter((row) => txt(row.event_type) === "REPLY_RECEIVED").length;

  const issuesOpen = rows.filter((lease) => txt(lease.issue_status) === "OPEN");
  const issuesResolved = rows.filter((lease) => txt(lease.issue_status) === "RESOLVED");
  const issuesFound = issuesOpen.length + issuesResolved.length;

  const atRisk = rows.filter((lease) => AT_RISK_STATUSES.has(txt(lease.status).toUpperCase()));
  const staying = rows.filter((lease) => txt(lease.status).toUpperCase() === "STAYING");

  const resolutionDays = issuesResolved
    .map((lease) => num(lease.days_to_resolve, null))
    .filter((value) => value != null && Number.isFinite(value));

  const avgResolutionDays = resolutionDays.length
    ? round1(resolutionDays.reduce((sum, value) => sum + value, 0) / resolutionDays.length)
    : 0;

  return {
    snapshot: "current",
    residents_in_window: residentsInWindow,
    check_ins_sent: checkInsSent,
    replies_received: repliesReceived,
    issues_found: issuesFound,
    issues_resolved: issuesResolved.length,
    avg_resolution_days: avgResolutionDays,
    at_risk_count: atRisk.length,
    staying_count: staying.length,
    turnover_exposure: atRisk.length * turnoverCost,
    exposure_recovered: issuesResolved.length * turnoverCost,
    updated_at: new Date().toISOString(),
  };
}

/**
 * Exposure for a cohort before anything has been sent - used in the generation
 * summary card so the prospect sees a number at the very start of the demo.
 */
function windowExposure(leases, cohort, config = {}) {
  const turnoverCost = num(config.avg_turnover_cost, 3900);
  const count = (leases || []).filter((lease) => txt(lease.cohort) === txt(cohort)).length;
  return count * turnoverCost;
}

/** Fields written to the Metrics table (strips the digest-only keys). */
function toMetricsRecord(metrics) {
  return {
    snapshot: metrics.snapshot || "current",
    residents_in_window: metrics.residents_in_window,
    check_ins_sent: metrics.check_ins_sent,
    replies_received: metrics.replies_received,
    issues_found: metrics.issues_found,
    issues_resolved: metrics.issues_resolved,
    avg_resolution_days: metrics.avg_resolution_days,
    at_risk_count: metrics.at_risk_count,
    turnover_exposure: metrics.turnover_exposure,
    exposure_recovered: metrics.exposure_recovered,
    updated_at: metrics.updated_at,
  };
}
function toArray(value) {
  if (!value) return [];
  return Array.isArray(value) ? value : [value];
}

function normalizeText(value) {
  return value === null || value === undefined ? "" : String(value).trim();
}

function foldForComparison(value) {
  return normalizeText(value)
    .normalize("NFKD")
    .replace(/[\u0300-\u036f]/g, "")
    .toLowerCase();
}

function normalizeBool(value) {
  if (value === true) return true;
  if (value === false) return false;
  return ["true", "1", "yes", "y"].includes(normalizeText(value).toLowerCase());
}

function buildConfig(configRows) {
  const config = {};
  for (const row of toArray(configRows)) {
    const key = normalizeText(row.key);
    if (key) config[key] = normalizeText(row.value);
  }
  return config;
}

function wordCount(text) {
  return normalizeText(text).split(/\s+/).filter(Boolean).length;
}

function hashHex(value) {
  let hash = 2166136261;
  const text = normalizeText(value);
  for (let i = 0; i < text.length; i += 1) {
    hash ^= text.charCodeAt(i);
    hash = Math.imul(hash, 16777619);
  }
  return (hash >>> 0).toString(16).toUpperCase().padStart(8, "0");
}

function refTokenForLease(lease, usedTokens = new Set()) {
  const existing = normalizeText(lease.ref_token).toUpperCase();
  if (/^R-[0-9A-F]{4}$/.test(existing) && !usedTokens.has(existing)) {
    usedTokens.add(existing);
    return existing;
  }

  for (let attempt = 0; attempt < 20; attempt += 1) {
    const token = `R-${hashHex(`${lease.lease_id}:${attempt}`).slice(0, 4)}`;
    if (!usedTokens.has(token)) {
      usedTokens.add(token);
      return token;
    }
  }

  throw new Error(`Could not allocate a unique ref_token for ${lease.lease_id}`);
}

function stripRefToken(subject) {
  return normalizeText(subject).replace(/\s*\[R-[0-9A-Fa-f]{4}\]\s*$/g, "").trim();
}

function appendRefToken(subject, refToken) {
  const base = stripRefToken(subject).replace(/\s+/g, " ");
  return `${base} [${refToken}]`;
}

function countQuestions(text) {
  return (normalizeText(text).match(/\?/g) || []).length;
}

function sentenceSimilarityKey(text) {
  return normalizeText(text)
    .toLowerCase()
    .replace(/\b[A-Z][a-z]+\b/g, "")
    .replace(/\b(cedar|willow|maple|river|pine|oak|birch|elm|spruce|meadow|hillcrest|sunset|orchard|vista|row|court|place|lane|terrace|tower|lofts|house|bend|gate|green|station|ridge|commons|point|walk|landing|run|square|heights)\b/g, "")
    .replace(/\b\d+\b/g, "")
    .replace(/\s+/g, " ")
    .trim();
}

function guardDraft(lease, subject, body) {
  const firstName = normalizeText(lease.tenant_first_name);
  const cleanSubject = stripRefToken(subject);
  const cleanBody = normalizeText(body);
  const combined = `${cleanSubject}\n${cleanBody}`;
  const violations = [];

  const banned = /\b(renew\w*|notice|offer|increase|expir\w*|deadline|sign(?:ing)?|lease\s+term|legal|evict\w*|nonrenew\w*|rent|price|amount|resident|tenant|occupant|valued)\b/i;
  const money = /(\$\s?\d|\d+\s?%|\bdollars?\b|\bcents?\b)/i;
  const dateLike = /\b(?:jan(?:uary)?|feb(?:ruary)?|mar(?:ch)?|apr(?:il)?|jun(?:e)?|jul(?:y)?|aug(?:ust)?|sep(?:t(?:ember)?)?|oct(?:ober)?|nov(?:ember)?|dec(?:ember)?)\b|\b\d{1,2}[/-]\d{1,2}(?:[/-]\d{2,4})?\b|\b\d{4}-\d{2}-\d{2}\b/i;
  const genericGreeting = /^(hi|hello|dear)\s+(resident|tenant|occupant|valued)\b/i;
  const wc = wordCount(cleanBody);

  if (!cleanSubject) violations.push("missing subject");
  if (cleanSubject.length > 70) violations.push("subject over 70 characters after token");
  if (!cleanBody) violations.push("missing body");
  if (banned.test(combined)) violations.push("banned rent, renewal, lease, legal, or generic-resident wording");
  if (money.test(combined)) violations.push("money or percentage wording");
  if (dateLike.test(combined)) violations.push("date or deadline-like wording");
  if (genericGreeting.test(cleanBody)) violations.push("generic resident greeting");
  if (wc < 35) violations.push("body under 35 words");
  if (wc > 95) violations.push("body over 95 words");
  if (firstName && !new RegExp(`\\b${foldForComparison(firstName).replace(/[.*+?^${}()|[\]\\]/g, "\\$&")}\\b`, "i").test(foldForComparison(cleanBody))) {
    violations.push("missing tenant first name");
  }
  if (countQuestions(cleanBody) !== 1) violations.push("body must contain exactly one question");
  if (/!|•|[\u{1F300}-\u{1FAFF}]/u.test(cleanBody)) violations.push("exclamation mark, bullet, or emoji");
  if (/i hope this finds you well/i.test(cleanBody)) violations.push("generic opening phrase");
  if (/generated|software|automation|ai-assisted|artificial intelligence/i.test(combined)) {
    violations.push("mentions automation or AI");
  }

  return {
    ok: violations.length === 0,
    violations,
    word_count: wc,
    question_count: countQuestions(cleanBody),
  };
}

function extractJsonCandidate(value) {
  if (value === null || value === undefined) return null;
  if (typeof value === "object") {
    if (value.subject && value.body) return value;
    if (Array.isArray(value.drafts)) return value;
    for (const key of ["output", "text", "content", "message", "data", "response"]) {
      const found = extractJsonCandidate(value[key]);
      if (found) return found;
    }
    if (Array.isArray(value)) {
      for (const item of value) {
        const found = extractJsonCandidate(item);
        if (found) return found;
      }
    }
    return null;
  }

  const text = normalizeText(value);
  if (!text) return null;
  try {
    return JSON.parse(text);
  } catch {
    const match = text.match(/\{[\s\S]*\}/);
    if (!match) return null;
    try {
      return JSON.parse(match[0]);
    } catch {
      return null;
    }
  }
}

function extractDraftBatch(openAiOutput) {
  const parsed = extractJsonCandidate(openAiOutput);
  if (!parsed || !Array.isArray(parsed.drafts)) return [];
  return parsed.drafts
    .map((draft) => ({
      lease_id: normalizeText(draft.lease_id),
      subject: normalizeText(draft.subject || draft.email_subject || draft.title || "A quick home check-in"),
      body: normalizeText(draft.body || draft.email_body || draft.message || draft.draft),
    }))
    .filter((draft) => draft.lease_id && draft.body);
}

function repairDraftForLease(lease, draft) {
  const firstName = normalizeText(lease.tenant_first_name);
  const repaired = {
    subject: normalizeText(draft.subject || "A quick home check-in"),
    body: normalizeText(draft.body),
  };

  if (firstName && repaired.body && !new RegExp(`\\b${foldForComparison(firstName).replace(/[.*+?^${}()|[\]\\]/g, "\\$&")}\\b`, "i").test(foldForComparison(repaired.body))) {
    const withoutGenericGreeting = repaired.body.replace(/^(hi|hello|dear)\s*[,:\-]?\s*/i, "");
    repaired.body = `Hi ${firstName}, ${withoutGenericGreeting}`;
  }

  return repaired;
}

function promptSystemInstructions() {
  return [
    "You write short, warm check-in messages from a residential property manager to current tenants.",
    "Purpose: open a conversation and find out whether anything about the home has gone unresolved. That is the only purpose.",
    "Hard rules: no rent, prices, amounts, percentages, renewal terms, lease terms, deadlines, dates, signing, notices, offers, increases, legal language, or expiration language.",
    "Never address anyone as Resident, Tenant, Occupant, or Valued.",
    "Never promise a repair, timeline, inspection, or visit.",
    "Never imply the tenant must reply or that anything happens if they do not.",
    "Never mention software, automation, AI, or that the message was generated.",
    "Each body must start with 'Hi {tenant_first_name},' and include one natural tenure reference, exactly one question about anything not sorted out, and the manager name as sign-off.",
    "Style: plain American English, 50 to 90 words, three or four short sentences, no exclamation marks, no bullets, no emoji, no 'I hope this finds you well'.",
    "Return only JSON matching the requested schema.",
  ].join("\n");
}

function buildDraftBatchPrompt(candidates, config) {
  const rows = candidates.map((lease) => ({
    lease_id: lease.lease_id,
